use verus::prelude::*;

verus! {

    /// Returns `true` iff every element of `a` equals `n`.
    ///
    /// Guarantees:
    ///   - If the function returns `true`, then for all valid indices `i`,
    ///     `a[i] == n`.
    ///   - If the function returns `false`, then there exists at least one
    ///     valid index `i` such that `a[i] != n`.
    pub fn all_elements_equal(a: &[i32], n: i32) -> bool
        ensures
            // If we return true, then every element equals n
            result ==> forall |i: usize| i < a.len() ==> a[i] == n,
        ensures
            // If we return false, there is some element not equal to n
            !result ==> exists |i: usize| i < a.len() && a[i] != n,
    {
        let mut i: usize = 0;
        // Scan through the array
        while i < a.len() {
            // Invariant: we have checked [0..i), and they all equal n
            invariant i <= a.len();
            invariant forall |j: usize| j < i ==> a[j] == n;
            decreases a.len() - i;

            if a[i] != n {
                // We found a counterexample at index i
                assert(i < a.len());
                assert(a[i] != n);
                // Witness the existential for the postcondition
                assert(exists(|j: usize| j < a.len() && a[j] != n));
                return false;
            }
            i += 1;
        }

        // We've checked all elements and found no counterexamples
        assert(i == a.len());
        assert(forall(|j: usize| j < a.len() ==> a[j] == n));
        true
    }

}